      "chunk_id": "marginalia_0",
      "quote": "Frequent hemodialysis versus standard hemodialysis for people with kidney failure: Systematic review and meta-analysis of randomized controlled trials",
      "reason": "The title explicitly includes the phrase \"Systematic review and meta-analysis\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Frequent hemodialysis versus standard hemodialysis for people with kidney failure: Systematic review and meta-analysis of randomized controlled trials",
      "reason": "The title clearly identifies the intervention (\"Frequent hemodialysis versus standard hemodialysis\") and the population (\"people with kidney failure\")."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "marginalia_0",
      "quote": "Frequent hemodialysis versus standard hemodialysis for people with kidney failure: Systematic review and meta-analysis of randomized controlled trials",
      "reason": "The title includes supplementary information regarding the study design included in the review (\"randomized controlled trials\")."
    }
  ],
  "confidence": 100
